async function seedNewRoadmaps() {
  console.log("\n🌱 Seeding new roadmaps...\n");

  const existingRoadmaps = await db.select().from(roadmaps);
  console.log(`  Found ${existingRoadmaps.length} existing roadmaps — skipping duplicates by title.`);

  let roadmapsAdded = 0;
  let stepsAdded = 0;

  for (const rm of NEW_ROADMAPS) {
    const alreadyExists = existingRoadmaps.find(r => r.title === rm.title);
    if (alreadyExists) {
      console.log(`  ⏭  Skipping (already exists): ${rm.title}`);
      continue;
    }
    const [created] = await db
      .insert(roadmaps)
      .values({ title: rm.title, description: rm.description, category: rm.category, icon: rm.icon })
      .returning();

    for (const step of rm.steps) {
      await db.insert(roadmapSteps).values({
        roadmapId: created.id,
        title: step.title,
        description: step.description,
        resources: JSON.stringify(step.resources),
        section: step.section,
        order: step.order,
      });
      stepsAdded++;
    }
    roadmapsAdded++;
    console.log(`  ✅ Added: ${rm.title} (${rm.steps.length} steps)`);
  }

  console.log(`\n🎉 Done! Added ${roadmapsAdded} new roadmaps with ${stepsAdded} total steps.`);
  process.exit(0);
}

seedNewRoadmaps().catch(err => {
  console.error("Seed failed:", err);
  process.exit(1);
});
